import React, { useState, useEffect } from 'react';
import { 
  Bus, 
  PlusCircle, 
  Users, 
  Ticket, 
  TrendingUp, 
  User as UserIcon, 
  CreditCard,
  Trash2,
  X,
  Shield,
  Key,
  DollarSign,
  Camera,
  Lock,
  Phone,
  Mail,
  UserCheck,
  History
} from 'lucide-react';

export default function Admin({ user = {}, activeTab = 'home' }) {
  // Bus Fleet State
  const [buses, setBuses] = useState(() => {
    const savedBuses = localStorage.getItem('app_buses');
    return savedBuses ? JSON.parse(savedBuses) : [
      { id: 101, name: 'Green Line Paribahan', route: 'Dhaka to Cox\'s Bazar', fare: '1500 BDT', seats: 36 },
      { id: 102, name: 'Ena Transport', route: 'Dhaka to Sylhet', fare: '800 BDT', seats: 40 },
      { id: 103, name: 'Hanif Enterprise', route: 'Dhaka to Chittagong', fare: '950 BDT', seats: 36 },
    ];
  });

  // REAL Users State (No dummy users — reads directly from signups)
  const [registeredUsers, setRegisteredUsers] = useState([]);

  // Selected User for viewing history modal
  const [selectedUserHistory, setSelectedUserHistory] = useState(null);

  // Permanent Profile Picture State
  const [profileImage, setProfileImage] = useState(() => {
    return localStorage.getItem(`avatar_${user?.emailOrPhone || 'admin'}`) || null;
  });

  // Load Real Registered Users from LocalStorage
  useEffect(() => {
    const loadedUsers = JSON.parse(localStorage.getItem('app_users') || '[]');
    setRegisteredUsers(loadedUsers);
  }, []);

  // Persist Buses
  useEffect(() => {
    localStorage.setItem('app_buses', JSON.stringify(buses));
  }, [buses]);

  // Password Change Form State
  const [passwordData, setPasswordData] = useState({ current: '', new: '', confirm: '' });
  const [pwdMsg, setPwdMsg] = useState({ type: '', text: '' });

  // Add Bus Modal State
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [newBus, setNewBus] = useState({ name: '', route: '', fare: '', seats: 40 });

  // Handle Permanent Photo Upload (Converts to Base64 string for LocalStorage)
  const handleImageChange = (e) => {
    const file = e.target.files[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        const base64Image = reader.result;
        setProfileImage(base64Image);
        localStorage.setItem(`avatar_${user?.emailOrPhone || 'admin'}`, base64Image);
      };
      reader.readAsDataURL(file);
    }
  };

  // Handle Password Update
  const handlePasswordSubmit = (e) => {
    e.preventDefault();
    if (!passwordData.current || !passwordData.new || !passwordData.confirm) {
      setPwdMsg({ type: 'error', text: 'Please fill in all password fields.' });
      return;
    }
    if (passwordData.new !== passwordData.confirm) {
      setPwdMsg({ type: 'error', text: 'New passwords do not match!' });
      return;
    }
    if (passwordData.new.length < 6) {
      setPwdMsg({ type: 'error', text: 'Password must be at least 6 characters.' });
      return;
    }

    setPwdMsg({ type: 'success', text: 'Password updated successfully!' });
    setPasswordData({ current: '', new: '', confirm: '' });
  };

  // Handle Deleting a Bus
  const handleDeleteBus = (id) => {
    setBuses(buses.filter(bus => bus.id !== id));
  };

  // Handle Adding a New Bus
  const handleAddBusSubmit = (e) => {
    e.preventDefault();
    if (!newBus.name || !newBus.route || !newBus.fare) return;

    const createdBus = {
      id: Math.floor(100 + Math.random() * 900),
      name: newBus.name,
      route: newBus.route,
      fare: newBus.fare.includes('BDT') ? newBus.fare : `${newBus.fare} BDT`,
      seats: Number(newBus.seats) || 36
    };

    setBuses([...buses, createdBus]);
    setNewBus({ name: '', route: '', fare: '', seats: 40 });
    setIsModalOpen(false);
  };

  return (
    <div style={styles.container}>
      {/* EVERYTHING RENDERED DIRECTLY IN HOME OPTION */}
      {activeTab === 'home' && (
        <>
          {/* Header */}
          <div style={styles.headerRow}>
            <div>
              <h2 style={styles.title}>Admin Panel ({user?.name || 'Administrator'})</h2>
              <p style={styles.subText}>System Overview & Management</p>
            </div>
            <button style={styles.addBtn} onClick={() => setIsModalOpen(true)}>
              <PlusCircle size={18} /> Add Bus Route
            </button>
          </div>

          {/* Key Metrics Grid */}
          <div style={styles.statsGrid}>
            <div style={styles.statCard}>
              <div style={styles.statIconWrapper}><Bus size={22} color="#ea580c" /></div>
              <div>
                <h3 style={styles.statValue}>{buses.length} Active Buses</h3>
                <span style={styles.statLabel}>Operational Fleets</span>
              </div>
            </div>

            <div style={styles.statCard}>
              <div style={styles.statIconWrapper}><Users size={22} color="#ea580c" /></div>
              <div>
                <h3 style={styles.statValue}>{registeredUsers.length} Real Users</h3>
                <span style={styles.statLabel}>Registered Accounts</span>
              </div>
            </div>

            <div style={styles.statCard}>
              <div style={styles.statIconWrapper}><Ticket size={22} color="#ea580c" /></div>
              <div>
                <h3 style={styles.statValue}>482 Tickets</h3>
                <span style={styles.statLabel}>Sold Today</span>
              </div>
            </div>

            <div style={styles.statCard}>
              <div style={styles.statIconWrapper}><TrendingUp size={22} color="#ea580c" /></div>
              <div>
                <h3 style={styles.statValue}>৳ 4,12,000</h3>
                <span style={styles.statLabel}>Total Revenue</span>
              </div>
            </div>
          </div>

          {/* Fleet Table */}
          <div style={styles.card}>
            <div style={styles.tableHeader}>
              <h3 style={styles.cardTitle}>Active Bus Fleet</h3>
              <span style={styles.countBadge}>{buses.length} Routes Configured</span>
            </div>

            <div style={{ overflowX: 'auto' }}>
              <table style={styles.table}>
                <thead>
                  <tr>
                    <th style={styles.th}>Bus ID</th>
                    <th style={styles.th}>Operator Name</th>
                    <th style={styles.th}>Route</th>
                    <th style={styles.th}>Ticket Price</th>
                    <th style={styles.th}>Total Seats</th>
                    <th style={{ ...styles.th, textAlign: 'right' }}>Actions</th>
                  </tr>
                </thead>
                <tbody>
                  {buses.map((bus) => (
                    <tr key={bus.id} style={styles.tr}>
                      <td style={styles.td}><span style={styles.idBadge}>#{bus.id}</span></td>
                      <td style={{ ...styles.td, fontWeight: '600', color: '#f4f4f5' }}>{bus.name}</td>
                      <td style={styles.td}>{bus.route}</td>
                      <td style={{ ...styles.td, color: '#22c55e', fontWeight: '600' }}>{bus.fare}</td>
                      <td style={styles.td}>{bus.seats} Seats</td>
                      <td style={{ ...styles.td, textAlign: 'right' }}>
                        <button style={styles.deleteBtn} title="Delete Bus Route" onClick={() => handleDeleteBus(bus.id)}>
                          <Trash2 size={16} />
                        </button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>

          {/* Admin Profile Section */}
          <div style={styles.card}>
            <div style={styles.flexTitle}>
              <UserIcon size={24} color="#ea580c" /> 
              <h2 style={styles.cardTitle}>Administrator Account</h2>
            </div>

            <div style={styles.profileSection}>
              {/* Permanent Photo Upload Area */}
              <div style={styles.avatarContainer}>
                <div style={styles.avatarCircle}>
                  {profileImage ? (
                    <img src={profileImage} alt="Profile" style={styles.avatarImg} />
                  ) : (
                    <UserIcon size={48} color="#a1a1aa" />
                  )}
                </div>
                <label htmlFor="photo-upload" style={styles.cameraBtn} title="Upload Permanent Photo">
                  <Camera size={14} color="#ffffff" />
                  <input 
                    id="photo-upload" 
                    type="file" 
                    accept="image/*" 
                    onChange={handleImageChange} 
                    style={{ display: 'none' }} 
                  />
                </label>
              </div>

              {/* Account Details */}
              <div style={styles.infoGroup}>
                <div style={styles.profileRow}>
                  <span style={styles.profileLabel}><UserIcon size={16} /> Name:</span>
                  <span style={styles.profileValue}>{user?.name || 'Super Administrator'}</span>
                </div>
                <div style={styles.profileRow}>
                  <span style={styles.profileLabel}><Mail size={16} /> Email:</span>
                  <span style={styles.profileValue}>{user?.emailOrPhone || 'admin@onlinebus.bd'}</span>
                </div>
                <div style={styles.profileRow}>
                  <span style={styles.profileLabel}><Phone size={16} /> Phone:</span>
                  <span style={styles.profileValue}>{user?.phone || '+880 1700-000000'}</span>
                </div>
                <div style={styles.profileRow}>
                  <span style={styles.profileLabel}><Shield size={16} /> Assigned Role:</span>
                  <span style={styles.roleBadge}>Super Admin Portal</span>
                </div>
              </div>
            </div>
          </div>

          {/* Registered Users Section */}
          <div style={styles.card}>
            <div style={styles.tableHeader}>
              <div style={styles.flexTitle}>
                <UserCheck size={22} color="#ea580c" />
                <h3 style={styles.cardTitle}>Real Registered Users</h3>
              </div>
              <span style={styles.countBadge}>{registeredUsers.length} Real Signups</span>
            </div>

            {registeredUsers.length === 0 ? (
              <div style={styles.emptyBox}>
                <Users size={32} color="#71717a" />
                <p>No registered users found yet. As soon as a user signs up on the registration page, their details and full history will automatically appear here.</p>
              </div>
            ) : (
              <div style={{ overflowX: 'auto' }}>
                <table style={styles.table}>
                  <thead>
                    <tr>
                      <th style={styles.th}>User ID</th>
                      <th style={styles.th}>Full Name</th>
                      <th style={styles.th}>Email / Username</th>
                      <th style={styles.th}>Phone</th>
                      <th style={styles.th}>Joined Date</th>
                      <th style={styles.th}>Role</th>
                      <th style={{ ...styles.th, textAlign: 'center' }}>User History</th>
                    </tr>
                  </thead>
                  <tbody>
                    {registeredUsers.map((u) => (
                      <tr key={u.id} style={styles.tr}>
                        <td style={styles.td}><span style={styles.userIdBadge}>{u.id}</span></td>
                        <td style={{ ...styles.td, fontWeight: '600', color: '#f4f4f5' }}>{u.name}</td>
                        <td style={styles.td}>{u.email}</td>
                        <td style={styles.td}>{u.phone || 'N/A'}</td>
                        <td style={styles.td}>{u.joined || 'Recent'}</td>
                        <td style={styles.td}>
                          <span style={u.role === 'admin' ? styles.roleBadgeAdmin : styles.activeBadge}>
                            {u.role || 'Passenger'}
                          </span>
                        </td>
                        <td style={{ ...styles.td, textAlign: 'center' }}>
                          <button 
                            style={styles.historyBtn} 
                            onClick={() => setSelectedUserHistory(u)}
                          >
                            <History size={14} /> View History
                          </button>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            )}
          </div>

          {/* Payment Gateways Section */}
          <div style={styles.card}>
            <div style={styles.flexTitle}>
              <CreditCard size={24} color="#ea580c" /> 
              <h2 style={styles.cardTitle}>Payment Gateway Settlement</h2>
            </div>
            <p style={{ color: '#a1a1aa', marginBottom: '20px' }}>
              Configure merchant credentials and live webhook endpoints for payment clearance in Bangladesh.
            </p>

            <div style={styles.gatewayGrid}>
              {['bKash Direct API', 'Nagad Merchant', 'Rocket Express', 'SSLCommerz Gateway'].map((gw, index) => (
                <div key={index} style={styles.gatewayCard}>
                  <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                    <div style={{ display: 'flex', alignItems: 'center', gap: '8px', color: '#f4f4f5', fontWeight: '600' }}>
                      <DollarSign size={18} color="#ea580c" /> {gw}
                    </div>
                    <span style={styles.connectedBadge}>Active</span>
                  </div>
                  <div style={styles.keyRow}>
                    <Key size={14} color="#71717a" />
                    <span style={{ fontSize: '0.8rem', color: '#71717a' }}>Merchant Key: ••••••••••••8892</span>
                  </div>
                </div>
              ))}
            </div>
          </div>

          {/* Change Password Section */}
          <div style={styles.card}>
            <div style={styles.flexTitle}>
              <Lock size={22} color="#ea580c" />
              <h3 style={styles.cardTitle}>Change Password</h3>
            </div>

            {pwdMsg.text && (
              <div style={pwdMsg.type === 'error' ? styles.errorAlert : styles.successAlert}>
                {pwdMsg.text}
              </div>
            )}

            <form onSubmit={handlePasswordSubmit} style={styles.passwordForm}>
              <div style={styles.formRow}>
                <div style={{ ...styles.fieldGroup, flex: 1 }}>
                  <label style={styles.modalLabel}>Current Password</label>
                  <input
                    type="password"
                    placeholder="••••••••"
                    value={passwordData.current}
                    onChange={(e) => setPasswordData({ ...passwordData, current: e.target.value })}
                    style={styles.modalInput}
                  />
                </div>
                <div style={{ ...styles.fieldGroup, flex: 1 }}>
                  <label style={styles.modalLabel}>New Password</label>
                  <input
                    type="password"
                    placeholder="••••••••"
                    value={passwordData.new}
                    onChange={(e) => setPasswordData({ ...passwordData, new: e.target.value })}
                    style={styles.modalInput}
                  />
                </div>
                <div style={{ ...styles.fieldGroup, flex: 1 }}>
                  <label style={styles.modalLabel}>Confirm New Password</label>
                  <input
                    type="password"
                    placeholder="••••••••"
                    value={passwordData.confirm}
                    onChange={(e) => setPasswordData({ ...passwordData, confirm: e.target.value })}
                    style={styles.modalInput}
                  />
                </div>
              </div>

              <button type="submit" style={styles.savePwdBtn}>Update Password</button>
            </form>
          </div>
        </>
      )}

      {/* USER HISTORY MODAL */}
      {selectedUserHistory && (
        <div style={styles.modalOverlay}>
          <div style={styles.modalContent}>
            <div style={styles.modalHeader}>
              <div>
                <h3>User History: {selectedUserHistory.name}</h3>
                <span style={{ fontSize: '0.8rem', color: '#a1a1aa' }}>ID: {selectedUserHistory.id} | Email: {selectedUserHistory.email}</span>
              </div>
              <button style={styles.closeBtn} onClick={() => setSelectedUserHistory(null)}>
                <X size={20} />
              </button>
            </div>

            <div style={{ marginTop: '16px' }}>
              <h4 style={{ color: '#ea580c', margin: '0 0 12px 0' }}>Activity & Booking Logs</h4>
              {selectedUserHistory.history && selectedUserHistory.history.length > 0 ? (
                <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
                  {selectedUserHistory.history.map((log, idx) => (
                    <div key={idx} style={styles.historyCard}>
                      <div style={{ fontWeight: '600', color: '#f4f4f5' }}>{log.type}</div>
                      <div style={{ fontSize: '0.8rem', color: '#a1a1aa' }}>{log.details}</div>
                      <div style={{ fontSize: '0.75rem', color: '#ea580c', marginTop: '4px' }}>{log.date}</div>
                    </div>
                  ))}
                </div>
              ) : (
                <p style={{ color: '#71717a', fontSize: '0.9rem' }}>No ticket purchases or bookings recorded for this user yet.</p>
              )}
            </div>
          </div>
        </div>
      )}

      {/* ADD BUS ROUTE MODAL */}
      {isModalOpen && (
        <div style={styles.modalOverlay}>
          <div style={styles.modalContent}>
            <div style={styles.modalHeader}>
              <h3>Add New Bus Route</h3>
              <button style={styles.closeBtn} onClick={() => setIsModalOpen(false)}><X size={20} /></button>
            </div>

            <form onSubmit={handleAddBusSubmit} style={styles.modalForm}>
              <div style={styles.fieldGroup}>
                <label style={styles.modalLabel}>Operator / Bus Name</label>
                <input
                  type="text"
                  placeholder="e.g. Shyamoli NR Travels"
                  value={newBus.name}
                  onChange={(e) => setNewBus({ ...newBus, name: e.target.value })}
                  style={styles.modalInput}
                  required
                />
              </div>

              <div style={styles.fieldGroup}>
                <label style={styles.modalLabel}>Route Details</label>
                <input
                  type="text"
                  placeholder="e.g. Dhaka to Rajshahi"
                  value={newBus.route}
                  onChange={(e) => setNewBus({ ...newBus, route: e.target.value })}
                  style={styles.modalInput}
                  required
                />
              </div>

              <div style={styles.formRow}>
                <div style={{ ...styles.fieldGroup, flex: 1 }}>
                  <label style={styles.modalLabel}>Fare (BDT)</label>
                  <input
                    type="text"
                    placeholder="e.g. 1100"
                    value={newBus.fare}
                    onChange={(e) => setNewBus({ ...newBus, fare: e.target.value })}
                    style={styles.modalInput}
                    required
                  />
                </div>

                <div style={{ ...styles.fieldGroup, flex: 1 }}>
                  <label style={styles.modalLabel}>Total Capacity</label>
                  <input
                    type="number"
                    value={newBus.seats}
                    onChange={(e) => setNewBus({ ...newBus, seats: e.target.value })}
                    style={styles.modalInput}
                    min="10"
                    max="60"
                    required
                  />
                </div>
              </div>

              <div style={styles.modalActions}>
                <button type="button" style={styles.cancelBtn} onClick={() => setIsModalOpen(false)}>Cancel</button>
                <button type="submit" style={styles.submitModalBtn}>Save Route</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}

const styles = {
  container: { display: 'flex', flexDirection: 'column', gap: '24px', color: '#ffffff' },
  headerRow: { display: 'flex', justifyContent: 'space-between', alignItems: 'center' },
  title: { margin: 0, fontSize: '1.5rem', fontWeight: '700' },
  subText: { color: '#a1a1aa', margin: '4px 0 0 0', fontSize: '0.9rem' },
  statsGrid: { display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(220px, 1fr))', gap: '16px' },
  statCard: { backgroundColor: '#27272a', padding: '20px', borderRadius: '16px', border: '1px solid #3f3f46', display: 'flex', alignItems: 'center', gap: '16px' },
  statIconWrapper: { backgroundColor: '#3f3f46', padding: '12px', borderRadius: '12px', display: 'flex', alignItems: 'center', justifyContent: 'center' },
  statValue: { margin: 0, fontSize: '1.15rem', fontWeight: '700', color: '#f4f4f5' },
  statLabel: { fontSize: '0.8rem', color: '#a1a1aa' },
  card: { backgroundColor: '#27272a', padding: '24px', borderRadius: '16px', border: '1px solid #3f3f46' },
  cardTitle: { margin: 0, fontSize: '1.2rem', fontWeight: '700' },
  flexTitle: { display: 'flex', alignItems: 'center', gap: '10px', marginBottom: '16px' },
  tableHeader: { display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '20px' },
  countBadge: { backgroundColor: '#3f3f46', color: '#a1a1aa', fontSize: '0.75rem', padding: '4px 10px', borderRadius: '20px', fontWeight: '600' },
  addBtn: { display: 'flex', alignItems: 'center', gap: '8px', backgroundColor: '#ea580c', color: '#ffffff', border: 'none', padding: '10px 18px', borderRadius: '10px', fontWeight: '600', fontSize: '0.9rem', cursor: 'pointer' },
  table: { width: '100%', borderCollapse: 'collapse', textAlign: 'left' },
  th: { padding: '14px 16px', borderBottom: '1px solid #3f3f46', color: '#a1a1aa', fontSize: '0.8rem', textTransform: 'uppercase', letterSpacing: '0.5px' },
  tr: { borderBottom: '1px solid #3f3f46' },
  td: { padding: '16px', fontSize: '0.9rem', color: '#d4d4d8' },
  idBadge: { backgroundColor: '#18181b', color: '#ea580c', padding: '4px 8px', borderRadius: '6px', fontWeight: '700', fontSize: '0.8rem' },
  userIdBadge: { backgroundColor: '#18181b', color: '#38bdf8', padding: '4px 8px', borderRadius: '6px', fontWeight: '700', fontSize: '0.8rem' },
  deleteBtn: { background: 'none', border: 'none', color: '#ef4444', cursor: 'pointer', padding: '6px', borderRadius: '6px' },
  profileSection: { display: 'flex', gap: '32px', alignItems: 'center', flexWrap: 'wrap', marginTop: '16px' },
  avatarContainer: { position: 'relative' },
  avatarCircle: { width: '96px', height: '96px', borderRadius: '50%', backgroundColor: '#18181b', border: '2px dashed #ea580c', display: 'flex', alignItems: 'center', justifyContent: 'center', overflow: 'hidden' },
  avatarImg: { width: '100%', height: '100%', objectFit: 'cover' },
  cameraBtn: { position: 'absolute', bottom: '0', right: '0', backgroundColor: '#ea580c', padding: '8px', borderRadius: '50%', cursor: 'pointer', display: 'flex' },
  infoGroup: { display: 'flex', flexDirection: 'column', gap: '12px', flex: 1 },
  profileRow: { display: 'flex', alignItems: 'center', borderBottom: '1px solid #3f3f46', paddingBottom: '8px' },
  profileLabel: { width: '140px', color: '#a1a1aa', fontWeight: '600', display: 'flex', alignItems: 'center', gap: '6px' },
  profileValue: { color: '#f4f4f5', fontWeight: '600' },
  roleBadge: { backgroundColor: '#ea580c', color: '#ffffff', fontSize: '0.75rem', padding: '4px 10px', borderRadius: '12px', fontWeight: '700' },
  roleBadgeAdmin: { backgroundColor: '#ef4444', color: '#ffffff', fontSize: '0.75rem', padding: '2px 8px', borderRadius: '10px', fontWeight: '600' },
  activeBadge: { backgroundColor: '#15803d', color: '#ffffff', fontSize: '0.75rem', padding: '2px 8px', borderRadius: '10px', fontWeight: '600' },
  passwordForm: { display: 'flex', flexDirection: 'column', gap: '16px', marginTop: '16px' },
  savePwdBtn: { alignSelf: 'flex-start', backgroundColor: '#ea580c', color: '#ffffff', border: 'none', padding: '10px 20px', borderRadius: '8px', fontWeight: '600', cursor: 'pointer' },
  errorAlert: { backgroundColor: '#ef4444', color: '#ffffff', padding: '10px 14px', borderRadius: '8px', fontSize: '0.85rem' },
  successAlert: { backgroundColor: '#22c55e', color: '#ffffff', padding: '10px 14px', borderRadius: '8px', fontSize: '0.85rem' },
  emptyBox: { display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', padding: '40px', textAlign: 'center', color: '#71717a', gap: '12px' },
  historyBtn: { display: 'inline-flex', alignItems: 'center', gap: '6px', backgroundColor: '#3f3f46', color: '#ffffff', border: 'none', padding: '6px 12px', borderRadius: '6px', fontSize: '0.8rem', cursor: 'pointer' },
  historyCard: { backgroundColor: '#18181b', padding: '12px', borderRadius: '8px', border: '1px solid #3f3f46' },
  gatewayGrid: { display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(220px, 1fr))', gap: '16px' },
  gatewayCard: { backgroundColor: '#18181b', padding: '18px', borderRadius: '12px', border: '1px solid #3f3f46', display: 'flex', flexDirection: 'column', gap: '12px' },
  connectedBadge: { backgroundColor: '#15803d', color: '#ffffff', fontSize: '0.7rem', padding: '2px 8px', borderRadius: '10px', fontWeight: '700' },
  keyRow: { display: 'flex', alignItems: 'center', gap: '6px' },
  modalOverlay: { position: 'fixed', top: 0, left: 0, right: 0, bottom: 0, backgroundColor: 'rgba(0, 0, 0, 0.75)', display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 1000 },
  modalContent: { backgroundColor: '#27272a', border: '1px solid #3f3f46', borderRadius: '16px', padding: '24px', width: '100%', maxWidth: '500px' },
  modalHeader: { display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: '20px' },
  closeBtn: { background: 'none', border: 'none', color: '#a1a1aa', cursor: 'pointer' },
  modalForm: { display: 'flex', flexDirection: 'column', gap: '16px' },
  fieldGroup: { display: 'flex', flexDirection: 'column', gap: '6px' },
  modalLabel: { fontSize: '0.8rem', color: '#a1a1aa', fontWeight: '600' },
  modalInput: { padding: '10px 14px', borderRadius: '8px', border: '1px solid #3f3f46', backgroundColor: '#18181b', color: '#ffffff', outline: 'none' },
  formRow: { display: 'flex', gap: '12px' },
  modalActions: { display: 'flex', justifyContent: 'flex-end', gap: '12px', marginTop: '12px' },
  cancelBtn: { padding: '10px 16px', borderRadius: '8px', border: 'none', backgroundColor: '#3f3f46', color: '#ffffff', fontWeight: '600', cursor: 'pointer' },
  submitModalBtn: { padding: '10px 18px', borderRadius: '8px', border: 'none', backgroundColor: '#ea580c', color: '#ffffff', fontWeight: '600', cursor: 'pointer' }
};
